import { useEffect, useRef } from "react";
import { placeSidePanels, pluginHost, useContributions } from "../plugins/host";
import { Rail } from "../plugins/Rail";
import { SettingsScreen } from "../settings/SettingsScreen";
import { HomeScreen } from "./HomeScreen";
import { useShellStore } from "./store";
import { TopBar } from "./TopBar";

export function App() {
  const theme = useShellStore((s) => s.theme);
  const view = useShellStore((s) => s.view);
  const setTheme = useShellStore((s) => s.setTheme);
  const setView = useShellStore((s) => s.setView);
  const init = useShellStore((s) => s.init);
  const backButtonRef = useRef<HTMLButtonElement>(null);
  const rails = placeSidePanels(useContributions(pluginHost.sidePanels));

  useEffect(() => {
    init();
  }, [init]);

  useEffect(() => {
    document.body.dataset.theme = theme;
  }, [theme]);

  // Hold-to-talk is focused-window only (decision D-10): plain renderer
  // keydown/keyup on right Alt while the app is focused - no global hooks,
  // no Input Monitoring permission, ever. Esc abandons.
  useEffect(() => {
    const down = (event: KeyboardEvent) => {
      const store = useShellStore.getState();
      if (event.key === "Escape") {
        if (store.phase === "recording") {
          store.abandonRecording();
        } else if (store.view === "settings") {
          store.setView("home");
        }
        return;
      }
      if (event.key === "Alt" && event.location === 2 && !event.repeat) {
        event.preventDefault();
        store.startRecording();
      }
    };
    const up = (event: KeyboardEvent) => {
      const store = useShellStore.getState();
      if (event.key === "Alt" && event.location === 2 && store.phase === "recording") {
        event.preventDefault();
        store.acceptRecording();
      }
    };
    window.addEventListener("keydown", down);
    window.addEventListener("keyup", up);
    return () => {
      window.removeEventListener("keydown", down);
      window.removeEventListener("keyup", up);
    };
  }, []);

  // Landing in settings moves focus to the back control so keyboard users
  // are not stranded in the previous screen's tree.
  useEffect(() => {
    if (view === "settings") {
      backButtonRef.current?.focus();
    }
  }, [view]);

  const home = view === "home";

  // The home shell (D5): two dock rails frame a STAGE that holds the fixed
  // geometry. An empty rail is zero-width (design/styles.css), so with both
  // empty the stage is the whole window and nothing below moves. The rails
  // are home-only in v1; Settings keeps its own centred composition. The
  // activity feed and the crew strip are panels on the left rail (phase 2,
  // the built-in plugin) - FYI lives in the feed (captain refinement 4a),
  // and the feed shows whenever it has lines, so an answered turn with zero
  // cards still leaves its trace there.
  return (
    <div
      style={{
        position: "absolute",
        inset: 0,
        background: "var(--bg-0)",
        overflow: "hidden",
        fontFamily: "var(--font-ui)",
      }}
    >
      <div style={{ position: "absolute", inset: 0, display: "flex", alignItems: "stretch" }}>
        {home && <Rail side="left" panels={rails.left} theme={theme} />}
        <div
          data-stage=""
          style={{
            position: "relative",
            flex: 1,
            minWidth: 0,
            // Stage-relative sizes (cqw) for anything that must not assume
            // the stage is the window.
            containerType: "inline-size",
          }}
        >
          {home && <HomeScreen />}
          {view === "settings" && <SettingsScreen />}
        </div>
        {home && <Rail side="right" panels={rails.right} theme={theme} />}
      </div>
      <TopBar
        view={view}
        theme={theme}
        onTheme={() => setTheme(theme === "dark" ? "light" : "dark")}
        onSettings={() => setView("settings")}
        onBack={() => setView("home")}
        backButtonRef={backButtonRef}
      />
    </div>
  );
}

import type { FrameTheme } from "@shared/plugins/frameDocument";
import type { RailSide } from "@shared/plugins/manifest";
import { useMemo, useSyncExternalStore } from "react";
import type { SidePanelContribution } from "./contributions";
import { FrameMount } from "./frames/FrameMount";
import { pluginHost } from "./host";
import { railStore, usePanelCollapsed } from "./railStore";
import { SidePanelChrome } from "./SidePanelChrome";

/**
 * One of the two dock rails (D5). The rail renders only its mounted
 * panels, and a panel whose source says `null` renders nothing at all - so
 * an empty rail is an empty element, and the stylesheet's `:empty` rule
 * gives it zero width, no padding, and no paint (design/styles.css). That
 * is the whole of "empty means invisible": no measurement, no flag, no
 * frame of chrome before the first data arrives.
 */
export function Rail({
  side,
  panels,
  theme,
}: {
  side: RailSide;
  panels: readonly SidePanelContribution[];
  /** The shell's theme, pushed into every frame the rail mounts. */
  theme: FrameTheme;
}) {
  return (
    <div data-rail={side}>
      {panels.map((panel) => (
        <PanelMount key={panel.id} panel={panel} theme={theme} />
      ))}
    </div>
  );
}

function PanelMount({ panel, theme }: { panel: SidePanelContribution; theme: FrameTheme }) {
  const content = useSyncExternalStore(panel.source.subscribe, panel.source.get, panel.source.get);
  const collapsed = usePanelCollapsed(panel.id);
  if (content === null) return null;
  return (
    <SidePanelChrome
      id={panel.id}
      title={panel.title}
      attribution={panel.attribution}
      size={panel.size}
      collapsed={collapsed}
      onToggleCollapsed={() => railStore.toggleCollapsed(panel.id)}
    >
      {panel.frame ? (
        <FramePanelBody panel={panel} theme={theme} />
      ) : (
        panel.Body && <panel.Body content={content} />
      )}
    </SidePanelChrome>
  );
}

/**
 * A Tier-2 panel: its template in the frame vehicle, inside the host's
 * chrome (docs/ui-plugins.md, phase 2). The mount lives as long as the
 * panel has something to show; its data is pushed over the bridge from the
 * reads the plugin declared. A panel is display: the only actions its
 * frame may raise are the pointing gestures the binding declared (the now
 * panel's "open this row"), and the controller refuses every other id.
 * A `fill` panel's frame takes the body's height; a `content` panel's
 * follows the document's own height as the bridge reports it, from zero,
 * so a strip is exactly as tall as it draws.
 */
function FramePanelBody({ panel, theme }: { panel: SidePanelContribution; theme: FrameTheme }) {
  const actions = useMemo(() => Object.keys(panel.actions ?? {}), [panel.actions]);
  if (!panel.frame) return null;
  return (
    <FrameMount
      title={panel.title}
      template={panel.frame}
      spec={{
        pluginId: panel.pluginId,
        reads: pluginHost.declaredReads(panel.pluginId),
        actions,
        onAction: (id, value) => panel.actions?.[id]?.(value),
      }}
      theme={theme}
      layout={panel.size === "fill" ? "fill" : "auto"}
      minAutoHeight={0}
      maxAutoHeight={FRAME_PANEL_MAX_AUTO_HEIGHT}
    />
  );
}

/** The most rail height a `content` panel's frame may grow to on its own. */
export const FRAME_PANEL_MAX_AUTO_HEIGHT = 320;

