@import "./tokens/fonts.css";
@import "./tokens/colors.css";
@import "./tokens/typography.css";
@import "./tokens/spacing.css";
@import "./tokens/effects.css";

/* Side rails: two dock columns framing the home stage. A rail is a flex
   column of host-framed panels at one fixed width token; an EMPTY rail is
   zero-width and paints nothing (no border, no header, no affordance), so a
   window with nothing docked is pixel-identical to one without rails. Not
   resizable. The stage insets over one motion token; it is never covered. */
[data-rail] {
  flex: 0 0 auto;
  box-sizing: border-box;
  width: var(--rail-width);
  min-width: 0;
  padding: var(--space-8) var(--space-3) var(--space-3);
  display: flex;
  flex-direction: column;
  gap: var(--space-3);
  overflow: hidden;
  resize: none;
  transition:
    width var(--dur-med) var(--ease-out),
    padding var(--dur-med) var(--ease-out);
}
[data-rail]:empty {
  width: 0;
  padding: 0;
}
[data-side-panel] {
  flex: 0 1 auto;
  min-height: 0;
  width: calc(var(--rail-width) - var(--space-3) * 2);
}
/* A `fill` panel takes the rail height its siblings leave; collapsed, it
   hugs its header like any other. Its body is a flex column so a frame
   inside can take the whole of it. */
[data-side-panel][data-side-panel-size="fill"]:not([data-side-panel-collapsed]) {
  flex: 1 1 auto;
}
[data-side-panel][data-side-panel-size="fill"] > [data-side-panel-body] {
  flex: 1 1 auto;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

