  stage: { x: number; width: number };
  characterCenter: number;
  inputCenter: number;
};

function geometry(page: Page): Promise<Geometry> {
  return page.evaluate(() => {
    const centerOf = (el: Element | null) => {
      const box = el?.getBoundingClientRect();
      return box ? box.x + box.width / 2 : Number.NaN;
    };
    const stage = document.querySelector("[data-stage]")?.getBoundingClientRect();
    return {
      innerWidth: window.innerWidth,
      railWidthToken: getComputedStyle(document.documentElement)
        .getPropertyValue("--rail-width")
        .trim(),
      rails: [...document.querySelectorAll("[data-rail]")].map((rail) => {
        const style = getComputedStyle(rail);
        return {
          side: rail.getAttribute("data-rail") ?? "",
          width: rail.getBoundingClientRect().width,
          children: rail.childElementCount,
          padding: style.padding,
          resize: style.resize,
        };
      }),
      panels: [...document.querySelectorAll("[data-side-panel]")].map((panel) => {
        const frame = panel.querySelector("iframe");
        return {
          id: panel.getAttribute("data-side-panel") ?? "",
          size: panel.getAttribute("data-side-panel-size") ?? "",
          collapsed: panel.hasAttribute("data-side-panel-collapsed"),
          height: panel.getBoundingClientRect().height,
          attributed: panel.querySelector("[data-side-panel-attribution]") !== null,
          frame: frame
            ? {
                title: frame.title,
                sandbox: frame.getAttribute("sandbox") ?? "",
                src: frame.getAttribute("src") ?? "",
              }
            : null,
        };
      }),
      stage: { x: stage?.x ?? Number.NaN, width: stage?.width ?? Number.NaN },
      characterCenter: centerOf(document.querySelector('[role="img"][aria-label^="Firstmate"]')),
      inputCenter: centerOf(document.querySelector("input")),
    };
  });
}

let launched: LaunchedApp;

test.beforeAll(async () => {
  launched = await launchApp({ withMockProvider: true });
  await expect(launched.page.locator("[data-screen-label]")).toHaveAttribute(
    "data-screen-label",
    "Null state",
  );
});

test.afterAll(async () => {
  await launched.close();
});

test("both rails are empty by default: zero width, nothing inside, the stage is the window", async () => {
  const g = await geometry(launched.page);
  expect(g.rails.map((rail) => rail.side)).toEqual(["left", "right"]);
  for (const rail of g.rails) {
    expect(rail.width, rail.side).toBe(0);
    expect(rail.children, rail.side).toBe(0);
    expect(rail.padding, rail.side).toBe("0px");
  }
  expect(g.panels).toEqual([]);
  expect(g.stage).toEqual({ x: 0, width: g.innerWidth });
  expect(Math.abs(g.characterCenter - g.innerWidth / 2)).toBeLessThanOrEqual(1);
  expect(Math.abs(g.inputCenter - g.innerWidth / 2)).toBeLessThanOrEqual(1);
});

test("the empty rails leave the window pixel-identical to a tree without rails", async () => {
  const { page } = launched;
  const shot = () =>
    page.screenshot({
      animations: "disabled",
      caret: "hide",
      // The character animates on its own clock; everything else is layout.
      mask: [page.getByRole("img", { name: /^Firstmate/ })],
      maskColor: "#000000",
    });
  const withRails = await shot();
  // Detach both rails, keeping them for the restore so React's tree is whole.
  await page.evaluate(() => {
    const rails = [...document.querySelectorAll("[data-rail]")];
    (window as unknown as { __fmRails: { rail: Element; next: Element | null }[] }).__fmRails =
      rails.map((rail) => ({ rail, next: rail.nextElementSibling }));
    for (const rail of rails) rail.remove();
  });
  expect(await page.locator("[data-rail]").count()).toBe(0);
  const withoutRails = await shot();
  await page.evaluate(() => {
    const frame = document.querySelector("[data-stage]")?.parentElement;
    const saved = (window as unknown as { __fmRails: { rail: Element; next: Element | null }[] })
      .__fmRails;
    for (const { rail, next } of saved) frame?.insertBefore(rail, next);
  });
  expect(await page.locator("[data-rail]").count()).toBe(2);
  expect(withRails.equals(withoutRails)).toBe(true);
});

test("the first task docks the feed, the crew strip, and the now panel: both rails open to the width token and inset the stage, never covering it", async () => {
  const { page } = launched;
  const before = await geometry(page);
  expect(before.railWidthToken).toBe("300px");

  const input = page.getByPlaceholder("type, or press/hold right ⌥ to talk");
  await input.click();
  await input.fill("commission a crewmate: refactor the auth middleware");
  await input.press("Enter");
  await expect(feedLine(page, /crewmate \d+ spawned - refactor the auth middleware/)).toBeVisible({
    timeout: 20_000,
  });
  await expect(crewStrip(page)).toBeVisible({ timeout: 20_000 });
  await expect(nowRow(page, "SCR-1")).toBeVisible({ timeout: 20_000 });
  await expect
    .poll(async () => (await geometry(page)).rails.map((rail) => rail.width), { timeout: 5_000 })
    .toEqual([300, 300]);

  const docked = await geometry(page);
  const railWidth = Number.parseFloat(docked.railWidthToken);
  expect(docked.rails[0]).toMatchObject({ side: "left", width: railWidth, resize: "none" });
  expect(docked.rails[1]).toMatchObject({ side: "right", width: railWidth, resize: "none" });
  // The stage insets by exactly one rail on each side and is never covered.
  expect(docked.stage).toEqual({ x: railWidth, width: docked.innerWidth - 2 * railWidth });
  const stageCenter = docked.innerWidth / 2;
  expect(Math.abs(docked.characterCenter - stageCenter)).toBeLessThanOrEqual(1);
  expect(Math.abs(docked.inputCenter - stageCenter)).toBeLessThanOrEqual(1);
  // No resize affordance exists: one token, not a persisted-layout problem.
  expect(await page.locator("[data-rail-resize], [data-rail] [class*=resize]").count()).toBe(0);

  // The three built-in panels, in rail then manifest order: the feed fills
  // the left rail's height the strip leaves, the strip hugs its content,
  // the now panel fills the right rail, and none is attributed - the app
  // never names itself in its own chrome.
  expect(docked.panels.map((panel) => [panel.id, panel.size, panel.collapsed])).toEqual([
    ["activity", "fill", false],
    ["crew", "content", false],
    ["now", "fill", false],
  ]);
  const [activity, crew, now] = docked.panels;
  expect(activity?.height).toBeGreaterThan((crew?.height ?? 0) * 3);
  expect(docked.panels.every((panel) => !panel.attributed)).toBe(true);
  // Every body is the frame vehicle: sandboxed, served over the host's scheme.
  expect(activity?.frame).toMatchObject({ title: "Activity", sandbox: "allow-scripts" });
  expect(crew?.frame).toMatchObject({ title: "Crew", sandbox: "allow-scripts" });
  expect(now?.frame).toMatchObject({ title: "Now", sandbox: "allow-scripts" });
  for (const panel of docked.panels) {
    expect(panel.frame?.src, panel.id).toMatch(/^app-frame:\/\/mount\/[0-9a-f-]+$/);
  }
});

test("collapse is host chrome: the header stays, the body and its frame go, the rail stays open", async () => {
  const { page } = launched;
  await page.getByRole("button", { name: "Collapse Activity" }).click();
  await expect(page.locator('[data-side-panel="activity"] [data-side-panel-body]')).toHaveCount(0);
  await expect(page.locator('iframe[title="Activity"]')).toHaveCount(0);
  const collapsed = await geometry(page);
  expect(collapsed.rails[0]?.width).toBe(300);
  expect(collapsed.panels.map((panel) => [panel.id, panel.collapsed])).toEqual([
    ["activity", true],
    ["crew", false],
    ["now", false],
  ]);
  // Collapsed, the feed hugs its header and the strip keeps its place below.
  const [activity, crew] = collapsed.panels;
  expect(activity?.height).toBeLessThan(crew?.height ?? 0);

  await page.getByRole("button", { name: "Expand Activity" }).click();
  await expect(page.locator('iframe[title="Activity"]')).toBeVisible();
  await expect(feedLine(page, /crewmate \d+ spawned - refactor the auth middleware/)).toBeVisible();
  const expanded = await geometry(page);
  expect(expanded.panels.map((panel) => panel.collapsed)).toEqual([false, false, false]);
});

test("settings is home-only territory for the rails, and the dock survives the trip", async () => {
  const { page } = launched;
  await page.getByRole("button", { name: "Settings" }).click();
  await expect(page.locator("[data-screen-label]")).toHaveAttribute(
    "data-screen-label",
    "Settings",
  );
  expect(await page.locator("[data-rail]").count()).toBe(0);
  expect(await page.locator("[data-side-panel]").count()).toBe(0);
  // The settings tabs come from the registry in declared order.
  await expect(page.getByRole("tab")).toHaveText(["General", "Subscriptions", "Observe"]);
  await page.keyboard.press("Escape");
  await expect(page.locator("[data-screen-label]")).toHaveAttribute(
    "data-screen-label",
    "Null state",
  );
  expect(await page.locator("[data-rail]").count()).toBe(2);
  // Back home, the panels still have something to show: the rail is open
  // at once, with the feed's lines painted again in a fresh mount.
  await expect
    .poll(async () => (await geometry(page)).rails.map((rail) => rail.width), { timeout: 5_000 })
    .toEqual([300, 300]);
  await expect(feedLine(page, /crewmate \d+ spawned - refactor the auth middleware/)).toBeVisible({
    timeout: 10_000,
  });
  await expect(crewStrip(page)).toBeVisible({ timeout: 10_000 });
  await expect(nowRow(page, "SCR-1")).toBeVisible({ timeout: 10_000 });
});

