import { expect, type Page, test } from "@playwright/test";
import type { TaskBoard } from "../../src/shared/tasks";
import { type LaunchedApp, launchApp } from "./launch";
import {
  EMIT_CARDS_PROMPT_MARKER,
  FM_SYSTEM_MARKER,
  MOCK_COMPLETION_TEXT,
  SPAWN_PROMPT_MARKER,
} from "./mockProvider";
import { feedLine, nowFrame, nowRow, recordFrame } from "./rails";

/**
 * The now panel and the task-record card against the built app
 * (task-system design section 10, P4). The right rail carries what IS: a
 * Tier-2 frame that paints the board the core pushes, minimal by default,
 * absent when nothing is open - so a plain turn, which files a question
 * task, docks nothing. A row painting within one coalescing window of the
 * core's write is the measurement this phase was accepted on; the numbers
 * come from two User Timing measures the frame script records (`now:lag`:
 * the newest row's own write time to its paint; `now:render`: one paint of
 * the groups), read back from inside the frame and printed.
 *
 * A click is a pointing gesture: a row opens the read-only record card,
 * whose only control is close, and while it is open the turn carries the
 * task as its hint; a row waiting on you brings its decision card to the
 * front instead. Both themes and the narrowest window are checked. Nothing
 * here writes a task through the panel or the card: every write happened
 * by talking to the Firstmate (design principle 5).
 */

/** From the core writing a row to the frame having painted it.
 * Local paints land ~40-55ms; this is a stall ceiling. CI's first iframe
 * paint can add a few hundred ms of warmup (279ms observed), the same
 * class rail-panels already budgets at 1s. */
const LAG_BUDGET_MS = 1_000;
/** One paint of the groups. */
const RENDER_BUDGET_MS = 50;

type Measures = { lag: number[]; render: number[] };

function measures(page: Page): Promise<Measures> {
  return nowFrame(page)
    .locator("body")
    .evaluate(() => ({
      lag: performance.getEntriesByName("now:lag").map((entry) => entry.duration),
      render: performance.getEntriesByName("now:render").map((entry) => entry.duration),
    }));
}

const max = (values: number[]) => Math.max(...values);

function report(name: string, values: number[]): void {
  const line = `n=${values.length} max=${max(values).toFixed(2)}ms`;
  test.info().annotations.push({ type: name, description: line });
  console.log(`[now-panel] ${name} ${line}`);
}

function board(page: Page): Promise<TaskBoard> {
  return page.evaluate(() => window.firstmate.tasks.board());
}

function rightRailWidth(page: Page): Promise<number> {
  return page.locator('[data-rail="right"]').evaluate((el) => el.getBoundingClientRect().width);
}

/** Chromium drops native clicks into a hidden window's sandboxed frames. */
async function clickInFrame(target: ReturnType<Page["locator"]>): Promise<void> {
  await target.evaluate((el) => (el as HTMLElement).click());
}


