import { join } from "node:path";
import { expect, type Page, test } from "@playwright/test";
import Database from "better-sqlite3";
import { type LaunchedApp, launchApp } from "./launch";
import { FINISH_PROMPT_MARKER, MOCK_COMPLETION_TEXT, MOCK_TRIAGE_SUMMARY } from "./mockProvider";
import { activityFrame, crewFrame, crewStrip, feedLine } from "./rails";

/**
 * The left rail's two built-in panels against the built app - the phase-2
 * streaming probe (docs/ui-plugins.md). The activity feed is the fastest-
 * updating surface in the app, so its Tier-2 frame is the measurement that
 * decides whether the vehicle can carry live data: every feed line the core
 * writes must reach the frame and be painted within budget, and a feed
 * that starts full (the persisted two hundred lines) must paint in one go
 * and stay pinned to the newest line.
 *
 * The numbers come from two User Timing measures the frame script records
 * (`feed:lag`: a line's own timestamp to its paint; `feed:render`: one
 * paint of the list), read back from inside the frame. They are asserted
 * against budgets and printed, so a run's result is a number, not a
 * feeling.
 */

/** From the core writing a line to the frame having painted it. */
const LAG_BUDGET_MS = 1_000;
/** One paint of the full two-hundred-line list. */
const FULL_RENDER_BUDGET_MS = 100;
const RETAINED_LINES = 200;

type Measures = { lag: number[]; render: number[] };

function measures(page: Page): Promise<Measures> {
  return activityFrame(page)
    .locator("body")
    .evaluate(() => ({
      lag: performance.getEntriesByName("feed:lag").map((entry) => entry.duration),
      render: performance.getEntriesByName("feed:render").map((entry) => entry.duration),
    }));
}

function feedRows(page: Page): Promise<string[]> {
  return activityFrame(page)
    .locator("[data-feed-row] .text")
    .evaluateAll((nodes) => nodes.map((node) => node.textContent ?? ""));
}

/** "pinned", or the scroller's metrics so a failed pin explains itself. */
async function feedPinned(page: Page): Promise<string> {
  const pin = await feedPin(page);
  return pin.pinned && pin.flag === "true" ? "pinned" : JSON.stringify(pin);

